{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would replace Tennessee Code § 49-6-417 with a requirement that local education agencies and public charter schools provide free feminine hygiene products for student use in eligible senior high schools.",
      "rationale": "Conveys the senior-high-school scope within public education, including public charter schools. The definitional cross-reference is not essential to this description."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "The bill defines the products to include tampons, panty liners, menstrual cups, sanitary napkins, and similar items.",
      "rationale": "Includes the listed examples but omits the broader definition covering products or materials designed for menstruation or other genital-tract secretions."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill would replace Tennessee Code § 49-6-417 with a requirement that local education agencies and public charter schools provide free feminine hygiene products for student use in eligible senior high schools. Products would have to be available in all women’s and girls’ bathrooms, all locker rooms, and with the school nurse in each building where instruction is provided. Bathrooms and locker rooms designated specifically for teachers or staff would be excluded.",
      "rationale": "Identifies the responsible entities, free provision requirement, eligible-school scope, required locations, instructional-building condition, and teacher/staff exception."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "provide free feminine hygiene products for student use in eligible senior high schools",
      "rationale": "Conveys that the products are designated for student use."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The Department of Education could develop policies and guidance to help schools comply.",
      "rationale": "Conveys the department's discretionary authority to develop policies and guidance for compliance; schools is a plain-language shorthand for the covered education entities and their governing bodies."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "States the effective date accurately."
    }
  ]
}
